using System.Globalization;

namespace X12Lens.Cli;

/// <summary>
/// Implements <c>x12lens inspect</c>: prints the envelope tree of one interchange.
/// </summary>
/// <remarks>
/// The output writer is injected rather than reached for through <c>Console.Out</c>, which
/// is the only reason dependency injection earns its place in a tool this small: it lets
/// the tests assert on the exact text this command produces instead of trusting a
/// screenshot. The sample output in the README is generated by this class and pinned by a
/// test, so it cannot drift away from what the program actually prints.
/// </remarks>
public sealed class InspectCommand
{
    private readonly X12Parser _parser;
    private readonly TextWriter _output;

    public InspectCommand(X12Parser parser, TextWriter output)
    {
        _parser = parser;
        _output = output;
    }

    public async Task RunAsync(string path, bool showSegments, CancellationToken cancellationToken = default)
    {
        var interchange = await _parser.ParseFileAsync(path, cancellationToken).ConfigureAwait(false);
        Write(interchange, Path.GetFileName(path), showSegments);
    }

    /// <summary>Renders an already parsed interchange. Split out so tests can call it directly.</summary>
    public void Write(Interchange interchange, string label, bool showSegments)
    {
        _output.WriteLine($"File          {label}");
        _output.WriteLine($"Delimiters    {interchange.Delimiters.Describe()}");
        _output.WriteLine();

        _output.WriteLine(
            $"Interchange   control {interchange.ControlNumber}   " +
            $"version {interchange.VersionId}   " +
            $"usage {interchange.UsageIndicator} ({(interchange.IsProduction ? "production" : "test")})");
        _output.WriteLine($"  Sender      {interchange.SenderQualifier} / {interchange.SenderId}");
        _output.WriteLine($"  Receiver    {interchange.ReceiverQualifier} / {interchange.ReceiverId}");
        _output.WriteLine($"  Created     {FormatIsaDate(interchange.Date)} {FormatTime(interchange.Time)}");
        _output.WriteLine(
            $"  Contents    {Plural(interchange.Groups.Count, "functional group")}, " +
            $"{Plural(interchange.TransactionSetCount, "transaction set")}, " +
            $"{Plural(interchange.SegmentCount, "segment")}");

        foreach (var group in interchange.Groups)
        {
            _output.WriteLine();
            _output.WriteLine(
                $"  Group       control {group.ControlNumber}   " +
                $"{group.FunctionalIdCode} ({group.FunctionalIdName ?? "unknown code"})   " +
                $"version {group.VersionCode}");

            foreach (var transactionSet in group.TransactionSets)
            {
                _output.WriteLine(
                    $"    Transaction set   control {transactionSet.ControlNumber}   " +
                    $"{transactionSet.Code} {transactionSet.Name ?? "(unknown code)"}   " +
                    $"{Plural(transactionSet.Segments.Count, "segment")}");

                if (showSegments)
                {
                    foreach (var segment in transactionSet.Segments)
                    {
                        _output.WriteLine(
                            $"      {segment.Position,5}  {segment.Id,-3}  " +
                            string.Join(" | ", segment.Elements));
                    }
                }
            }
        }
    }

    /// <summary>ISA09 is YYMMDD, with no century. GS04 has one. This is not an accident of my sample data.</summary>
    private static string FormatIsaDate(string yymmdd) =>
        DateTime.TryParseExact(yymmdd, "yyMMdd", CultureInfo.InvariantCulture, DateTimeStyles.None, out var date)
            ? date.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)
            : yymmdd;

    private static string FormatTime(string hhmm) =>
        hhmm.Length == 4 ? $"{hhmm[..2]}:{hhmm[2..]}" : hhmm;

    private static string Plural(int count, string noun) =>
        count == 1 ? $"1 {noun}" : $"{count} {noun}s";
}
